static __always_inline void kvm_riscv_vcpu_swap_in_host_state(struct kvm_vcpu *vcpu)
{
	...
	if (riscv_has_extension_unlikely(RISCV_ISA_EXT_SMSTATEEN) &&
	    (cfg->hstateen0 & SMSTATEEN0_SSTATEEN0))
		smcsr->sstateen0 = csr_swap(CSR_SSTATEEN0,
					    vcpu->arch.host_sstateen0);
}

if (riscv_has_extension_unlikely(RISCV_ISA_EXT_SMSTATEEN)) {
	cfg->hstateen0 |= SMSTATEEN0_HSENVCFG;
	if (riscv_isa_extension_available(isa, SSAIA))
		cfg->hstateen0 |= SMSTATEEN0_AIA_IMSIC |
				  SMSTATEEN0_AIA |
				  SMSTATEEN0_AIA_ISEL;
	if (riscv_isa_extension_available(isa, SMSTATEEN))
		cfg->hstateen0 |= SMSTATEEN0_SSTATEEN0;
}

void kvm_arch_vcpu_put(struct kvm_vcpu *vcpu)
{
	...
	kvm_riscv_vcpu_guest_fp_save(&vcpu->arch.guest_context, vcpu->arch.isa);
	kvm_riscv_vcpu_host_fp_restore(&vcpu->arch.host_context);
	...
	csr->vsstatus = csr_read(CSR_VSSTATUS);
	/* no sstateen/hstateen save here */
}

switch (magic) {
case END_MAGIC: ... return 0;
case RISCV_V_MAGIC: ... err = __restore_v_state(regs, sc_ext_ptr); break;
case RISCV_ZICFISS_MAGIC: ... err = __restore_cfiss_state(regs, sc_ext_ptr); break;
default: return -EINVAL;
}

static inline int kvm_riscv_vcpu_smstateen_set_csr(struct kvm_vcpu *vcpu,
						   unsigned long reg_num,
						   unsigned long reg_val)
{
	struct kvm_vcpu_smstateen_csr *csr = &vcpu->arch.smstateen_csr;
	if (reg_num >= sizeof(struct kvm_riscv_smstateen_csr) / sizeof(unsigned long))
		return -EINVAL;
	((unsigned long *)csr)[reg_num] = reg_val;
	return 0;
}
